eason" maxlength="1000" required></label><label class="my-3"><input type="checkbox" name="confirmed" value="1" required> Potvrzuji zápis skutečného podkladu a jeho stavu.</label><button class="btn btn-primary">Uložit neměnnou verzi</button></form></details><p><a href="financial_decisions_admin.php">Založit nový samostatný podklad</a></p><h2 class="h4">Posledních 200 verzí</h2><table class="table"><thead><tr><th>Podklad</th><th>Stav</th><th>Platnost</th><th>Novější verze</th></tr></thead><tbody><?php foreach($rows as$r):?><tr><td><a href="?id=<?=(int)$r['id']?>"><?=financialDecisionH('#'.$r['id'].' '.$r['title'])?></a></td><td><?=financialDecisionH($states[$r['state']])?></td><td><?=financialDecisionH($r['valid_from'].' – '.($r['valid_to']??''))?></td><td><?php if($r['newer_id']):?><a href="?id=<?=(int)$r['newer_id']?>">#<?=(int)$r['newer_id']?></a><?php endif;?></td></tr><?php endforeach;?></tbody></table></main></body></html>
